import XCTest
import Network
import CryptoKit
@preconcurrency @testable import Boardcast

final class WireConnectionTests: XCTestCase {
    private func wire() -> WireConnection { WireConnection(NWConnection(host: "127.0.0.1", port: 9, using: .tcp)) }

    func testCloseBeforeStartResumesWithCancellation() async {
        let connection = wire()
        connection.close()
        connection.close()
        do { try await connection.start(); XCTFail("Closed connection started") }
        catch { XCTAssertTrue(error is CancellationError) }
    }

    func testRepeatedCloseResumesPendingReadOnce() async {
        for _ in 0..<32 {
            let connection = wire()
            let read = Task { try await connection.read(1) }
            connection.close()
            connection.close()
            do { _ = try await read.value; XCTFail("Closed read succeeded") }
            catch { XCTAssertTrue(error is CancellationError) }
        }
    }

    func testTaskCancellationUnblocksPendingRead() async {
        let connection = wire()
        let read = Task { try await connection.read(1) }
        read.cancel()
        do { _ = try await read.value; XCTFail("Cancelled read succeeded") }
        catch { XCTAssertTrue(error is CancellationError) }
    }

    func testInvalidReadSizeRejectedWithoutNetworkAllocation() async {
        let connection = wire()
        do { _ = try await connection.read(WireConnection.maxFrame + 1); XCTFail("Unbounded read accepted") }
        catch { XCTAssertFalse(error is CancellationError) }
        connection.close()
    }
    // Generated by the actual Windows Core WireProtocol.WriteAsync (BoardcastJson.Options).
    // The Windows hello advertises chunks, but its offer is legacy after a Mac hello omits capabilities.
    private static let windowsTranscript = Data(base64Encoded: "")!

    func testWindowsFramesDecodeWithLegacyPayloadAndReceipt() async throws {
        let parameters = NWParameters.tcp
        parameters.requiredLocalEndpoint = .hostPort(host: "127.0.0.1", port: .any)
        let listener = try NWListener(using: parameters, on: .any)
        let ready = expectation(description: "Loopback listener ready")
        let accepted = expectation(description: "Loopback connection accepted")
        final class Incoming: @unchecked Sendable {
            private let lock = NSLock()
            private var value: WireConnection?
            func store(_ connection: WireConnection) { lock.lock(); value = connection; lock.unlock() }
            func take() -> WireConnection? { lock.lock(); defer { lock.unlock() }; return value }
        }
        let incoming = Incoming()
        listener.stateUpdateHandler = { state in if case .ready = state { ready.fulfill() } }
        listener.newConnectionHandler = { incoming.store(WireConnection($0)); accepted.fulfill() }
        listener.start(queue: DispatchQueue(label: "Boardcast.WireFixture"))
        defer { listener.cancel(); incoming.take()?.close() }
        await fulfillment(of: [ready], timeout: 3)
        let port = try XCTUnwrap(listener.port)
        let client = WireConnection(NWConnection(host: "127.0.0.1", port: port, using: .tcp))
        defer { client.close() }
        async let connected: Void = client.start()
        await fulfillment(of: [accepted], timeout: 3)
        let server = try XCTUnwrap(incoming.take())
        try await server.start()
        try await connected
        client.setIdleTimeout(1)
        let writer = Task {
            // Fragment frame headers, JSON and hashes so exact reads cannot depend on TCP packets.
            let bytes = Self.windowsTranscript
            for offset in stride(from: 0, to: bytes.count, by: 17) {
                try await server.send(bytes.subdata(in: offset..<min(offset + 17, bytes.count)))
            }
        }
        defer { writer.cancel() }
        let hello = try await client.readJSON(WireMessage.self)
        try TransferService.validateHello(hello, fingerprint: String(repeating: "a", count: 64))
        XCTAssertEqual(hello.peer?.name, "Windows 📄")
        let request = try await client.readJSON(WireMessage.self)
        let offer = try XCTUnwrap(request.offer)
        XCTAssertEqual(request.type, "offer")
        XCTAssertEqual(offer.entries.map(\.isDirectory), [true, false, false, true])
        XCTAssertEqual(offer.totalBytes, 7)
        for entry in offer.entries where !entry.isDirectory {
            let payload = try await client.read(Int(entry.size))
            let digest = try await client.read(32)
            XCTAssertEqual(digest, Data(SHA256.hash(data: payload)))
            if entry.size > 0 { XCTAssertEqual(payload, Data([0, 1, 255, 42, 10, 13, 128])) }
        }
        let receipt = try await client.readJSON(WireMessage.self)
        XCTAssertEqual(receipt.type, "complete")
        XCTAssertEqual(receipt.message, "Received and verified.")
        try await writer.value
    }

    func testHelloNameLimitMatchesWindowsUTF16Units() throws {
        var hello = WireMessage(type: "hello", version: 1,
            peer: PeerInfo(fingerprint: String(repeating: "a", count: 64), name: String(repeating: "中", count: 256)))
        XCTAssertNoThrow(try TransferService.validateHello(hello, fingerprint: String(repeating: "a", count: 64)))
        hello.peer?.name = String(repeating: "📄", count: 128)
        XCTAssertNoThrow(try TransferService.validateHello(hello, fingerprint: String(repeating: "a", count: 64)))
        hello.peer?.name.append("a")
        XCTAssertThrowsError(try TransferService.validateHello(hello, fingerprint: String(repeating: "a", count: 64)))
        hello.peer?.name = "Windows"
        XCTAssertThrowsError(try TransferService.validateHello(hello, fingerprint: String(repeating: "b", count: 64)))
        hello.version = 2
        XCTAssertThrowsError(try TransferService.validateHello(hello, fingerprint: String(repeating: "a", count: 64)))
    }

    func testMacMessagesSelectWindowsLegacyDefaults() throws {
        let peer = PeerInfo(fingerprint: String(repeating: "a", count: 64), name: "Mac")
        let hello = try XCTUnwrap(JSONSerialization.jsonObject(with: JSONEncoder().encode(
            WireMessage(type: "hello", version: 1, peer: peer))) as? [String: Any])
        XCTAssertNil(hello["capabilities"])
        XCTAssertNil(hello["chunks"])
        let encodedPeer = try XCTUnwrap(hello["peer"] as? [String: Any])
        XCTAssertFalse(encodedPeer["appVersion"] is NSNull)
        XCTAssertFalse(encodedPeer["runtime"] is NSNull)
        let offer = TransferOffer(senderName: "Mac", senderFingerprint: peer.fingerprint,
            entries: [TransferEntry(relativePath: "folder", size: 0, isDirectory: true),
                      TransferEntry(relativePath: "folder/empty.dat", size: 0, isDirectory: false)])
        let request = try XCTUnwrap(JSONSerialization.jsonObject(with: JSONEncoder().encode(
            WireMessage(type: "offer", version: 1, offer: offer))) as? [String: Any])
        XCTAssertNil(request["capabilities"])
        XCTAssertNil(request["chunks"])
        let encodedOffer = try XCTUnwrap(request["offer"] as? [String: Any])
        XCTAssertEqual((encodedOffer["id"] as? String)?.count, 32)
        let entries = try XCTUnwrap(encodedOffer["entries"] as? [[String: Any]])
        XCTAssertEqual(entries[0]["relativePath"] as? String, "folder")
        XCTAssertEqual(entries[0]["isDirectory"] as? Bool, true)
        XCTAssertEqual(entries[1]["isDirectory"] as? Bool, false)
        XCTAssertEqual(entries[1]["size"] as? Int, 0)
    }
}
